#pragma once

const char INDEX_HTML[] PROGMEM = R"HTML(
<!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Часы</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    min-height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
    background: linear-gradient(135deg, #0f0c29, #302b63, #24243e);
    background-size: 400% 400%;
    animation: shift 15s ease infinite;
    font-family: 'Segoe UI', Arial, sans-serif;
    overflow: hidden;
  }

  @keyframes shift {
    0% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
    100% { background-position: 0% 50%; }
  }

  .card {
    text-align: center;
    padding: 60px 80px;
    border-radius: 24px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.12);
    backdrop-filter: blur(20px);
    box-shadow: 0 25px 60px rgba(0, 0, 0, 0.45);
  }

  .time {
    font-size: clamp(64px, 14vw, 150px);
    font-weight: 700;
    letter-spacing: 4px;
    color: #fff;
    text-shadow: 0 0 30px rgba(120, 140, 255, 0.55);
    font-variant-numeric: tabular-nums;
  }

  .seconds {
    font-size: 0.35em;
    color: #8ec5ff;
    vertical-align: super;
    margin-left: 6px;
  }

  .date {
    margin-top: 14px;
    font-size: clamp(16px, 2.5vw, 24px);
    color: rgba(255, 255, 255, 0.75);
    letter-spacing: 2px;
    text-transform: capitalize;
  }

  .fullscreen-btn {
    margin-top: 30px;
    padding: 12px 28px;
    border-radius: 30px;
    border: 1px solid rgba(255, 255, 255, 0.25);
    background: rgba(255, 255, 255, 0.08);
    color: #fff;
    font-size: 15px;
    cursor: pointer;
    transition: background 0.3s, transform 0.2s;
  }

  .fullscreen-btn:hover {
    background: rgba(255, 255, 255, 0.18);
    transform: scale(1.05);
  }
</style>
</head>
<body>

<div class="card">
  <div class="time"><span id="t">00:00</span><span class="seconds" id="s">00</span></div>
  <div class="date" id="d"></div>
  <button class="fullscreen-btn" onclick="toggleFs()">Полный экран</button>
</div>

<script>
  const tEl = document.getElementById('t');
  const sEl = document.getElementById('s');
  const dEl = document.getElementById('d');

  function tick() {
    const n = new Date();

    const hh = String(n.getHours()).padStart(2, '0');
    const mm = String(n.getMinutes()).padStart(2, '0');
    const ss = String(n.getSeconds()).padStart(2, '0');

    tEl.textContent = hh + ':' + mm;
    sEl.textContent = ss;

    dEl.textContent = n.toLocaleDateString('ru-RU',
      { weekday: 'long', day: 'numeric', month: 'long' });
  }

  tick();
  setInterval(tick, 250);

  function toggleFs() {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen();
    } else {
      document.exitFullscreen();
    }
  }
</script>

</body>
</html>
)HTML";
